cat > main.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
)

func main() {
	src := `
package p
import "example.com/typeprint/extlib"
func f() (int, error) { return extlib.B() }
func g() error { err := extlib.A(); return err }
func h() error { return nil }
`
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "p.go", src, 0)
	conf := types.Config{Importer: importer.Default()}
	info := &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
		Defs: make(map[*ast.Ident]types.Object),
		Uses: make(map[*ast.Ident]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
	}
	_, err := conf.Check("p", fset, []*ast.File{f}, info)
	fmt.Printf("check err: %v\n", err)
	ast.Inspect(f, func(n ast.Node) bool {
		if ret, ok := n.(*ast.ReturnStmt); ok {
			fmt.Printf("return at %v results %d\n", fset.Position(ret.Pos()), len(ret.Results))
			for i, e := range ret.Results {
				tv, ok := info.Types[e]
				fmt.Printf("  result %d expr %T type %v mode %v ok %v\n", i, e, tv.Type, tv.Mode, ok)
				if call, ok := e.(*ast.CallExpr); ok {
					fmt.Printf("    is call fun %T\n", call.Fun)
				}
				if ident, ok := e.(*ast.Ident); ok {
					fmt.Printf("    is ident %s def %v use %v\n", ident.Name, info.Defs[ident], info.Uses[ident])
				}
			}
		}
		return true
	})
}
EOF
