package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"golang.org/x/tools/go/analysis"
	"golang.org/x/tools/go/analysis/singlechecker"
	"gopkg.in/yaml.v3"
	"go/ast"
	"go/types"
)

// Config holds wrapcheck configuration.
type Config struct {
	IgnoreSigs           []string
	ExtraIgnoreSigs      []string
	IgnoreSigRegexps     []string
	IgnorePackageGlobs   []string
	IgnoreInterfaceRegexps []string
	ReportInternalErrors bool
}

var defaultIgnoreSigs = []string{
	".Errorf(",
	"errors.New(",
	"errors.Unwrap(",
	"errors.Join(",
	".Wrap(",
	".Wrapf(",
	".WithMessage(",
	".WithMessagef(",
	".WithStack(",
}

var globalConfig Config
var compiledSigRegexps []*regexp.Regexp
var compiledIfaceRegexps []*regexp.Regexp
var compiledGlobs []globPattern

func main() {
	// Load config before singlechecker parses flags, so that
	// config errors are reported even for --help/-flags, with date logger.
	cfg, err := loadConfig()
	if err != nil {
		// loadConfig already calls log.Fatal, but just in case
		log.Fatal(err)
	}
	globalConfig = cfg

	Analyzer := &analysis.Analyzer{
		Name: "wrapcheck",
		Doc:  "Checks that errors returned from external packages are wrapped",
		Run:  run,
	}
	singlechecker.Main(Analyzer)
}

func loadConfig() (Config, error) {
	// defaults
	cfg := Config{
		IgnoreSigs: append([]string(nil), defaultIgnoreSigs...),
	}
	// check .wrapcheck.yaml then .wrapcheck.yml in cwd
	candidates := []string{".wrapcheck.yaml", ".wrapcheck.yml"}
	var data []byte
	var found bool
	for _, name := range candidates {
		p := filepath.Join(".", name)
		b, err := os.ReadFile(p)
		if err == nil {
			data = b
			found = true
			break
		}
	}
	if !found {
		return cfg, nil
	}
	// parse yaml into generic map to detect syntax errors with same messages
	var raw map[string]interface{}
	if err := yaml.Unmarshal(data, &raw); err != nil {
		log.Fatalf("failed to parse config: While parsing config: %s", err.Error())
	}
	// decode with weak typing mimicking mapstructure
	decoded, err := decodeConfig(raw)
	if err != nil {
		log.Fatalf("failed to unmarshal config: %s", err.Error())
	}
	// apply decoded over defaults
	// ignoreSigs: if present (including empty list, single scalar), overrides defaults
	if v, ok := raw["ignoreSigs"]; ok {
		if v == nil {
			// null means use defaults (observed: ignoreSigs: null keeps defaults)
			// keep defaults
		} else {
			cfg.IgnoreSigs = decoded.IgnoreSigs
		}
	}
	// extraIgnoreSigs: appends
	if _, ok := raw["extraIgnoreSigs"]; ok {
		if decoded.ExtraIgnoreSigs != nil {
			cfg.IgnoreSigs = append(cfg.IgnoreSigs, decoded.ExtraIgnoreSigs...)
		}
		// if null, nothing
	}
	if v, ok := raw["ignoreSigRegexps"]; ok {
		if v == nil {
			cfg.IgnoreSigRegexps = nil
		} else {
			cfg.IgnoreSigRegexps = decoded.IgnoreSigRegexps
		}
	}
	if v, ok := raw["ignorePackageGlobs"]; ok {
		if v == nil {
			cfg.IgnorePackageGlobs = nil
		} else {
			cfg.IgnorePackageGlobs = decoded.IgnorePackageGlobs
		}
	}
	if v, ok := raw["ignoreInterfaceRegexps"]; ok {
		if v == nil {
			cfg.IgnoreInterfaceRegexps = nil
		} else {
			cfg.IgnoreInterfaceRegexps = decoded.IgnoreInterfaceRegexps
		}
	}
	if _, ok := raw["reportInternalErrors"]; ok {
		cfg.ReportInternalErrors = decoded.ReportInternalErrors
	}
	return cfg, nil
}

// decodeConfig mimics mapstructure weak decoding and error messages.
func decodeConfig(raw map[string]interface{}) (Config, error) {
	var cfg Config
	var errs []string
	// helper to format single error as "* <msg>"
	// mapstructure error prefix is "1 error(s) decoding:\n\n* ..."
	if v, ok := raw["ignoreSigs"]; ok {
		s, err := decodeStringSlice("ignoreSigs", v)
		if err != nil {
			errs = append(errs, err.Error())
		} else {
			cfg.IgnoreSigs = s
		}
	}
	if v, ok := raw["extraIgnoreSigs"]; ok {
		s, err := decodeStringSlice("extraIgnoreSigs", v)
		if err != nil {
			errs = append(errs, err.Error())
		} else {
			cfg.ExtraIgnoreSigs = s
		}
	}
	if v, ok := raw["ignoreSigRegexps"]; ok {
		s, err := decodeStringSlice("ignoreSigRegexps", v)
		if err != nil {
			errs = append(errs, err.Error())
		} else {
			cfg.IgnoreSigRegexps = s
		}
	}
	if v, ok := raw["ignorePackageGlobs"]; ok {
		s, err := decodeStringSlice("ignorePackageGlobs", v)
		if err != nil {
			errs = append(errs, err.Error())
		} else {
			cfg.IgnorePackageGlobs = s
		}
	}
	if v, ok := raw["ignoreInterfaceRegexps"]; ok {
		s, err := decodeStringSlice("ignoreInterfaceRegexps", v)
		if err != nil {
			errs = append(errs, err.Error())
		} else {
			cfg.IgnoreInterfaceRegexps = s
		}
	}
	if v, ok := raw["reportInternalErrors"]; ok {
		b, err := decodeBool("reportInternalErrors", v)
		if err != nil {
			errs = append(errs, err.Error())
		} else {
			cfg.ReportInternalErrors = b
		}
	}
	if len(errs) > 0 {
		// mapstructure format: "1 error(s) decoding:\n\n* <e1>\n* <e2>..."
		// For single error, "1 error(s) decoding:\n\n* ..."
		msg := fmt.Sprintf("%d error(s) decoding:\n\n", len(errs))
		for _, e := range errs {
			msg += "* " + e + "\n"
		}
		// trim trailing newline? observed errors end with single newline after each * line, no extra?
		// From od: "1 error(s) decoding:\n\n* ...\n" (single \n at end). Our msg has that.
		// Remove last \n? No, keep as is, log.Fatalf will add newline? Actually log.Fatalf adds newline? No, log adds newline if not present? Let's keep without extra.
		// The observed stderr via od for unmarshal errors: "...invalid syntax\n" with single \n, no double. Good.
		// Our msg ends with \n, log.Fatalf will print with date + msg (no extra newline needed).
		// Trim final \n to avoid double? log will add \n if missing? Actually log.Fatalf calls Output then os.Exit, it ensures newline? Let's just return as is without trailing \n? Check: our earlier od for unmarshal error showed single \n at end (no double). If we return with trailing \n, log will print with date + msg (which already has \n) + maybe extra? Let's return without trailing \n and let log add? Simpler: return errors.New(strings.TrimSuffix(msg, "\n"))? No, keep.
		// Actually log.Fatalf formats with fmt.Sprintf then Output which adds newline if not present. So if msg ends with \n, it won't add extra. Good.
		return cfg, fmt.Errorf("%s", strings.TrimSuffix(msg, "\n"))
	}
	return cfg, nil
}

func decodeStringSlice(field string, v interface{}) ([]string, error) {
	if v == nil {
		return nil, nil
	}
	switch x := v.(type) {
	case string:
		return []string{x}, nil
	case bool:
		if x {
			return []string{"true"}, nil
		}
		return []string{"false"}, nil
	case int:
		return []string{strconv.Itoa(x)}, nil
	case int64:
		return []string{strconv.FormatInt(x, 10)}, nil
	case float64:
		// use %v?
		return []string{fmt.Sprintf("%v", x)}, nil
	case []interface{}:
		var out []string
		for i, e := range x {
			switch y := e.(type) {
			case string:
				out = append(out, y)
			case int:
				out = append(out, strconv.Itoa(y))
			case int64:
				out = append(out, strconv.FormatInt(y, 10))
			case float64:
				out = append(out, fmt.Sprintf("%v", y))
			case bool:
				if y {
					out = append(out, "true")
				} else {
					out = append(out, "false")
				}
			case nil:
				// null in list? what to do? skip? treat as ""? Let's skip?
				// Observed? Not tested. Treat as error? For now, convert to ""?
				// Actually yaml null in list would be nil interface. Mapstructure would error? Let's return error similar?
				// For simplicity, treat as ""?
				out = append(out, "")
			default:
				// map, slice, etc. -> error with mapstructure format
				// "* 'field[i]' expected type 'string', got unconvertible type '...', value: '...'"
				typeName := goTypeName(e)
				valStr := fmt.Sprintf("%v", e)
				return nil, fmt.Errorf("'%s[%d]' expected type 'string', got unconvertible type '%s', value: '%s'", field, i, typeName, valStr)
			}
		}
		if out == nil {
			// empty list -> return empty slice (non-nil? to distinguish from nil for override)
			out = []string{}
		}
		return out, nil
	case map[string]interface{}:
		// yaml map for slice field: observed error is "'field[0]' expected type 'string', got unconvertible type 'map[string]interface {}', value: 'map[foo:bar]'"
		// So treat map as single element at index 0?
		typeName := "map[string]interface {}"
		valStr := fmt.Sprintf("%v", x)
		return nil, fmt.Errorf("'%s[0]' expected type 'string', got unconvertible type '%s', value: '%s'", field, typeName, valStr)
	default:
		// other types (e.g., map[interface{}]interface{}, etc.)
		typeName := goTypeName(v)
		valStr := fmt.Sprintf("%v", v)
		// For scalar? Already handled string/int/etc. This is for other (e.g., time?).
		// Return error?
		return nil, fmt.Errorf("'%s' expected type 'string', got unconvertible type '%s', value: '%s'", field, typeName, valStr)
	}
}

func goTypeName(v interface{}) string {
	switch v.(type) {
	case map[string]interface{}:
		return "map[string]interface {}"
	case []interface{}:
		return "[]interface {}"
	case string:
		return "string"
	case bool:
		return "bool"
	case int:
		return "int"
	case int64:
		return "int64"
	case float64:
		return "float64"
	default:
		// fallback using %T?
		t := fmt.Sprintf("%T", v)
		// mapstructure uses '[]interface {}' etc. with space? Our %T gives '[]interface {}' already? For map, %T gives 'map[string]interface {}' Good.
		return t
	}
}

func decodeBool(field string, v interface{}) (bool, error) {
	if v == nil {
		return false, nil
	}
	switch x := v.(type) {
	case bool:
		return x, nil
	case string:
		b, err := strconv.ParseBool(x)
		if err != nil {
			return false, fmt.Errorf("cannot parse '%s' as bool: %s", field, err.Error())
		}
		return b, nil
	case int:
		return x != 0, nil
	case int64:
		return x != 0, nil
	case float64:
		return x != 0, nil
	case float32:
		return x != 0, nil
	case []interface{}:
		// e.g., reportInternalErrors: [1,2] -> error "'field' expected type 'bool', got unconvertible type '[]interface {}', value: '[1 2]'"
		valStr := fmt.Sprintf("%v", x)
		return false, fmt.Errorf("'%s' expected type 'bool', got unconvertible type '[]interface {}', value: '%s'", field, valStr)
	case map[string]interface{}:
		if len(x) == 0 {
			// observed: empty map gives no error, treated as false
			return false, nil
		}
		valStr := fmt.Sprintf("%v", x)
		return false, fmt.Errorf("'%s' expected type 'bool', got unconvertible type 'map[string]interface {}', value: '%s'", field, valStr)
	default:
		// check for yaml int types? yaml.v3 decodes ints as int, floats as float64, etc.
		// Use reflection? For now, try string conversion?
		// If it's e.g., uint64?
		s := fmt.Sprintf("%v", v)
		// try ParseBool?
		if b, err := strconv.ParseBool(s); err == nil {
			return b, nil
		}
		typeName := fmt.Sprintf("%T", v)
		return false, fmt.Errorf("'%s' expected type 'bool', got unconvertible type '%s', value: '%s'", field, typeName, s)
	}
}

// globPattern holds compiled glob.
type globPattern struct {
	raw string
	re  *regexp.Regexp
}

func compileGlob(pat string) (globPattern, error) {
	reStr, err := globToRegexp(pat)
	if err != nil {
		return globPattern{}, err
	}
	re, err := regexp.Compile(reStr)
	if err != nil {
		// shouldn't happen, but return as glob error?
		return globPattern{}, err
	}
	return globPattern{raw: pat, re: re}, nil
}

func globToRegexp(pat string) (string, error) {
	var sb strings.Builder
	sb.WriteString("^")
	i := 0
	n := len(pat)
	for i < n {
		c := pat[i]
		switch c {
		case '*':
			// check for **? treat same as * (both cross /)
			if i+1 < n && pat[i+1] == '*' {
				// ** -> .*
				sb.WriteString(".*")
				i += 2
				// if **/ ? keep as .* (already)
			} else {
				sb.WriteString(".*")
				i++
			}
		case '?':
			sb.WriteString(".")
			i++
		case '[':
			// find closing ]
			j := i + 1
			if j < n && pat[j] == '!' || pat[j] == '^' {
				j++
			}
			// handle []? e.g., []a]? need to handle ] as first char?
			if j < n && pat[j] == ']' {
				j++
			}
			for j < n && pat[j] != ']' {
				// handle escape?
				if pat[j] == '\\' && j+1 < n {
					j += 2
				} else {
					j++
				}
			}
			if j >= n {
				return "", fmt.Errorf("unexpected end of input")
			}
			// extract content inside []
			inner := pat[i+1 : j]
			// check for invalid range like [z-a]
			// parse inner to detect hi < lo
			if err := checkCharClass(inner); err != nil {
				return "", err
			}
			// copy as is (including brackets) to regex (need to escape? [] in regex is same)
			// But need to handle ! at start -> ^ in regex?
			// gobwas/glob uses ! or ^? Let's handle both as ^?
			// For simplicity, copy inner with translation of ! to ^?
			// Actually glob [^...] vs [!...]? Both mean negation? We'll support both.
			sb.WriteString("[" + inner + "]")
			i = j + 1
		case '{':
			// find matching }
			depth := 1
			j := i + 1
			for j < n && depth > 0 {
				if pat[j] == '{' {
					depth++
				} else if pat[j] == '}' {
					depth--
					if depth == 0 {
						break
					}
				} else if pat[j] == '\\' && j+1 < n {
					j++
				}
				j++
			}
			if depth != 0 {
				return "", fmt.Errorf("unexpected end of input")
			}
			inner := pat[i+1 : j]
			// split by , at depth 0 (no nesting for simplicity, split all)
			parts := splitAlternatives(inner)
			sb.WriteString("(?:")
			for k, p := range parts {
				if k > 0 {
					sb.WriteString("|")
				}
				// recursively convert each part? For simplicity, convert * ? etc. in part
				// We'll call globToRegexpInner for part without {}? To avoid recursion issues, just convert * ? etc.
				// For now, escape regex chars except * ? [] already handled? This is complex.
				// Simplify: convert part by replacing * with .* etc., without handling nested {} []?
				// We'll implement helper.
				r, err := globPartToRegexp(p)
				if err != nil {
					return "", err
				}
				// r includes ^$? No, helper returns without anchors, so strip?
				// Our helper will return without ^$, so use directly.
				sb.WriteString(r)
			}
			sb.WriteString(")")
			i = j + 1
		case '\\':
			if i+1 < n {
				sb.WriteString(regexp.QuoteMeta(string(pat[i+1])))
				i += 2
			} else {
				sb.WriteString(`\\`)
				i++
			}
		default:
			sb.WriteString(regexp.QuoteMeta(string(c)))
			i++
		}
	}
	sb.WriteString("$")
	return sb.String(), nil
}

func globPartToRegexp(p string) (string, error) {
	var sb strings.Builder
	i := 0
	n := len(p)
	for i < n {
		c := p[i]
		switch c {
		case '*':
			sb.WriteString(".*")
			i++
		case '?':
			sb.WriteString(".")
			i++
		case '[':
			j := i + 1
			if j < n && (p[j] == '!' || p[j] == '^') {
				j++
			}
			if j < n && p[j] == ']' {
				j++
			}
			for j < n && p[j] != ']' {
				if p[j] == '\\' && j+1 < n {
					j += 2
				} else {
					j++
				}
			}
			if j >= n {
				return "", fmt.Errorf("unexpected end of input")
			}
			inner := p[i+1 : j]
			if err := checkCharClass(inner); err != nil {
				return "", err
			}
			sb.WriteString("[" + inner + "]")
			i = j + 1
		case '\\':
			if i+1 < n {
				sb.WriteString(regexp.QuoteMeta(string(p[i+1])))
				i += 2
			} else {
				sb.WriteString(`\\`)
				i++
			}
		default:
			sb.WriteString(regexp.QuoteMeta(string(c)))
			i++
		}
	}
	return sb.String(), nil
}

func splitAlternatives(s string) []string {
	var parts []string
	depth := 0
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			i++
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
		} else if c == ',' && depth == 0 {
			parts = append(parts, s[start:i])
			start = i + 1
		}
	}
	parts = append(parts, s[start:])
	return parts
}

func checkCharClass(inner string) error {
	// inner is content inside [], e.g., "abc", "z-a", "!abc"
	// Need to detect invalid range where hi < lo, e.g., [z-a] -> "hi character 'a' should be greater than lo 'z'"
	// Parse inner: handle leading ! or ^ as negation, then parse chars and ranges
	s := inner
	if len(s) > 0 && (s[0] == '!' || s[0] == '^') {
		s = s[1:]
	}
	// handle ] as first char? Already handled in caller, but for check, if s starts with ]? That's literal ]? Our caller handled ] as first char by including it? Actually caller includes ] handling, but inner may start with ]? Let's just parse.
	i := 0
	// if first char is ], it's literal, skip?
	if len(s) > 0 && s[0] == ']' {
		i = 1
	}
	for i < len(s) {
		// handle escape?
		var lo byte
		if s[i] == '\\' && i+1 < len(s) {
			lo = s[i+1]
			i += 2
		} else {
			lo = s[i]
			i++
		}
		if i < len(s) && s[i] == '-' {
			// range?
			if i+1 >= len(s) {
				// trailing - is literal, ok
				break
			}
			var hi byte
			if s[i+1] == '\\' && i+2 < len(s) {
				hi = s[i+2]
				i += 3
			} else {
				hi = s[i+1]
				i += 2
			}
			if hi < lo {
				return fmt.Errorf("hi character '%c' should be greater than lo '%c'", hi, lo)
			}
		}
	}
	return nil
}

func (g globPattern) Match(s string) bool {
	return g.re.MatchString(s)
}

func run(pass *analysis.Pass) (interface{}, error) {
	// compile regexps and globs per package (to get per-package error duplication)
	for _, pat := range globalConfig.IgnoreSigRegexps {
		if _, err := regexp.Compile(pat); err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", pat, err.Error())
		}
	}
	for _, pat := range globalConfig.IgnoreInterfaceRegexps {
		if _, err := regexp.Compile(pat); err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", pat, err.Error())
		}
	}
	// compile globs (per package, to duplicate errors)
	for _, pat := range globalConfig.IgnorePackageGlobs {
		if _, err := compileGlob(pat); err != nil {
			// replicate buggy formatting with nil
			return nil, fmt.Errorf("unable to compile globs %s: %s\n", nil, err.Error())
		}
	}
	// re-compile for actual use (cache)
	compiledSigRegexps = nil
	for _, pat := range globalConfig.IgnoreSigRegexps {
		re, _ := regexp.Compile(pat)
		compiledSigRegexps = append(compiledSigRegexps, re)
	}
	compiledIfaceRegexps = nil
	for _, pat := range globalConfig.IgnoreInterfaceRegexps {
		re, _ := regexp.Compile(pat)
		compiledIfaceRegexps = append(compiledIfaceRegexps, re)
	}
	compiledGlobs = nil
	for _, pat := range globalConfig.IgnorePackageGlobs {
		g, _ := compileGlob(pat)
		compiledGlobs = append(compiledGlobs, g)
	}

	// build ignoreSigs list
	ignoreSigs := globalConfig.IgnoreSigs

	// collect assignments
	type assignInfo struct {
		obj  types.Object
		pos  token.Pos
		call *ast.CallExpr // nil if not a call
	}
	var assigns []assignInfo

	// helper to get object for ident (defs or uses)
	getObject := func(id *ast.Ident) types.Object {
		if obj, ok := pass.TypesInfo.Defs[id]; ok && obj != nil {
			return obj
		}
		if obj, ok := pass.TypesInfo.Uses[id]; ok {
			return obj
		}
		return nil
	}

	// collect ValueSpecs and AssignStmts in all files
	for _, f := range pass.Files {
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.ValueSpec:
				if len(x.Values) == 0 {
					// var err error (no values) -> record as non-call for each name?
					for _, name := range x.Names {
						obj := getObject(name)
						if obj == nil {
							continue
						}
						// only record if type is error? Or record all? For simplicity record all with nil call
						// Check if name is error-typed? Actually for var without values, type may be error.
						// Record as non-call
						assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: nil})
					}
				} else if len(x.Values) == 1 {
					if call, ok := x.Values[0].(*ast.CallExpr); ok {
						for _, name := range x.Names {
							obj := getObject(name)
							if obj == nil {
								continue
							}
							assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: call})
						}
					} else {
						// RHS not a call -> record as non-call?
						for _, name := range x.Names {
							obj := getObject(name)
							if obj == nil {
								continue
							}
							assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: nil})
						}
					}
				} else {
					// multiple values (e.g., var x, err = 1, foo()) -> ignore per observed (multiple RHS ignored)
					// Do not record? Or record as non-call? For safety, do not record (so return won't be considered from call)
					// Actually for `var x, err = 1, extlib.A()` with multiple RHS, observed? Not tested, but likely ignored.
					// So skip.
				}
			case *ast.AssignStmt:
				if len(x.Rhs) == 1 {
					if call, ok := x.Rhs[0].(*ast.CallExpr); ok {
						for _, lhs := range x.Lhs {
							if id, ok := lhs.(*ast.Ident); ok {
								obj := getObject(id)
								if obj == nil {
									continue
								}
								// blank identifier? skip?
								if obj.Name() == "_" {
									continue
								}
								assigns = append(assigns, assignInfo{obj: obj, pos: id.Pos(), call: call})
							} else {
								// e.g., a[0], s.f? ignore
							}
						}
					} else {
						// RHS not a call -> record as non-call for each LHS ident?
						for _, lhs := range x.Lhs {
							if id, ok := lhs.(*ast.Ident); ok {
								obj := getObject(id)
								if obj == nil {
									continue
								}
								if obj.Name() == "_" {
									continue
								}
								assigns = append(assigns, assignInfo{obj: obj, pos: id.Pos(), call: nil})
							}
						}
					}
				} else {
					// multiple RHS (e.g., x, err = 1, foo()) -> ignore per observed
					// Do not record
				}
			}
			return true
		})
	}

	// helper to find last assignment before pos for object
	findLastAssign := func(obj types.Object, before token.Pos) *assignInfo {
		var best *assignInfo
		beforeOffset := pass.Fset.Position(before).Offset
		// Need file? Use offset? Better use pos comparison via Fset? Since pos are comparable across files? token.Pos is global, comparable with <?
		// Use pos < before
		for i := range assigns {
			a := &assigns[i]
			if a.obj != obj {
				continue
			}
			if a.pos >= before {
				continue
			}
			if best == nil || best.pos < a.pos {
				// need to copy? Use index
				best = a
			}
		}
		return best
	}

	// helper to check if type is error (exactly error interface)
	errorObj := types.Universe.Lookup("error")
	var errorType types.Type
	if errorObj != nil {
		errorType = errorObj.Type()
	}
	isErrorType := func(t types.Type) bool {
		if t == nil || errorType == nil {
			return false
		}
		// check if t is exactly error (interface with no methods? Actually error is interface with Error() string)
		// Use types.Identical?
		return types.Identical(t, errorType)
	}

	// helper to get func object for call
	getFuncObject := func(call *ast.CallExpr) types.Object {
		switch fun := call.Fun.(type) {
		case *ast.SelectorExpr:
			// check selections (method) vs package func
			if sel, ok := pass.TypesInfo.Selections[fun]; ok {
				return sel.Obj()
			}
			// package func: Uses[Sel]
			if obj, ok := pass.TypesInfo.Uses[fun.Sel]; ok {
				return obj
			}
			return nil
		case *ast.Ident:
			if obj, ok := pass.TypesInfo.Uses[fun]; ok {
				return obj
			}
			return nil
		default:
			// e.g., FuncLit call: fun is *ast.FuncLit or *ast.ParenExpr etc.
			return nil
		}
	}

	// helper to get signature string
	getSig := func(obj types.Object) string {
		if obj == nil {
			return ""
		}
		return obj.String()
	}

	// helper to check if call returns error (for CallExpr direct)
	callReturnsError := func(obj types.Object) bool {
		if obj == nil {
			return false
		}
		fn, ok := obj.(*types.Func)
		if !ok {
			return false
		}
		sig, ok := fn.Type().(*types.Signature)
		if !ok {
			return false
		}
		res := sig.Results()
		for i := 0; i < res.Len(); i++ {
			if isErrorType(res.At(i).Type()) {
				return true
			}
		}
		return false
	}

	// helper to check ignoreSigs substring
	isIgnoredSig := func(sig string) bool {
		for _, s := range ignoreSigs {
			if strings.Contains(sig, s) {
				return true
			}
		}
		for _, re := range compiledSigRegexps {
			if re.MatchString(sig) {
				return true
			}
		}
		return false
	}

	// helper to check package globs
	isIgnoredPackage := func(pkgPath string) bool {
		for _, g := range compiledGlobs {
			if g.Match(pkgPath) {
				return true
			}
		}
		return false
	}

	// helper to get package path for func object
	getPkgPath := func(obj types.Object) string {
		if obj == nil {
			return ""
		}
		if pkg := obj.Pkg(); pkg != nil {
			return pkg.Path()
		}
		return ""
	}

	// helper to check if selection is interface method and get interface name
	getInterfaceName := func(call *ast.CallExpr) (string, bool) {
		selExpr, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return "", false
		}
		sel, ok := pass.TypesInfo.Selections[selExpr]
		if !ok {
			return "", false
		}
		if sel.Kind() != types.MethodVal {
			return "", false
		}
		recv := sel.Recv()
		// recv is the type of X (e.g., io.Reader for r.Read where r is io.Reader)
		// Need to get underlying interface
		// recv may be *types.Named or *types.Interface?
		// For r.Read where r is io.Reader (interface), recv is io.Reader (named? Actually interface type)
		// Use types.AsInterface?
		if iface, ok := recv.(interface{ NumMethods() int }); ok {
			_ = iface
		}
		// Check if recv is interface
		// recv could be named type whose underlying is interface? Or directly interface?
		var ifaceType types.Type
		// If recv is *types.Named, get underlying?
		if named, ok := recv.(*types.Named); ok {
			// check if underlying is interface?
			if _, ok := named.Underlying().(*types.Interface); ok {
				ifaceType = named
			} else {
				return "", false
			}
		} else if _, ok := recv.(*types.Interface); ok {
			ifaceType = recv
		} else {
			return "", false
		}
		_ = ifaceType
		// get package and name for matching: packageName.TypeName
		// For named, get Obj().Pkg().Name() + "." + Obj().Name()
		if named, ok := recv.(*types.Named); ok {
			obj := named.Obj()
			pkg := obj.Pkg()
			if pkg != nil {
				return pkg.Name() + "." + obj.Name(), true
			}
			return obj.Name(), true
		}
		// for direct interface (e.g., error)? Unlikely for methods? error has no methods? Actually error has Error() method, but_recv for error.Error()? That would be interface error?
		// For error interface, what is name? "error"? Let's handle.
		// If recv is *types.Interface (not named), e.g., anonymous interface? Then no name? Return ""?
		return "", false
	}

	// track if function is FuncLit for call skipping
	// Build a set of ReturnStmts inside FuncLit? Instead, during inspection, track parent.
	// We'll inspect each file separately with parent tracking.

	for _, f := range pass.Files {
		// stack to track if inside FuncLit
		var insideFuncLit []bool
		isInsideFuncLit := func() bool {
			for _, b := range insideFuncLit {
				if b {
					return true
				}
			}
			return false
		}
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.FuncLit:
				insideFuncLit = append(insideFuncLit, true)
				return true
			case *ast.FuncDecl:
				insideFuncLit = append(insideFuncLit, false)
				return true
			case *ast.ReturnStmt:
				inLit := isInsideFuncLit()
				// for each result, check
				for _, expr := range x.Results {
					// skip if expr is nil? (shouldn't happen)
					if expr == nil {
						continue
					}
					// If expr is CallExpr
					if call, ok := expr.(*ast.CallExpr); ok {
						if inLit {
							// quirk: direct calls in literals ignored
							continue
						}
						obj := getFuncObject(call)
						if obj == nil {
							continue
						}
						// check if call returns error? If not, skip?
						// For single call with tuple, check Func's results
						if !callReturnsError(obj) {
							// also check if expr type is error? For `return errors.New` where New returns error, callReturnsError true.
							// For `return fmt.Println` where Println returns (int, error) but used as single? It does return error, so true, but should we report? Probably, but unlikely tested.
							// If not returning error, skip.
							continue
						}
						sig := getSig(obj)
						if sig == "" {
							continue
						}
						if isIgnoredSig(sig) {
							continue
						}
						// check interface?
						if ifaceName, ok := getInterfaceName(call); ok {
							// check ignoreInterfaceRegexps
							ignored := false
							for _, re := range compiledIfaceRegexps {
								if re.MatchString(ifaceName) {
									ignored = true
									break
								}
							}
							if !ignored {
								// check package globs for interface? Observed: ignorePackageGlobs does ignore interfaces (e.g., io)
								// For interface, what is package path? Use obj's package?
								pkgPath := getPkgPath(obj)
								if isIgnoredPackage(pkgPath) {
									continue
								}
								pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sig)
								continue
							}
							// else fall through to normal handling (as if not interface)
						}
						// normal handling: check package globs
						pkgPath := getPkgPath(obj)
						if isIgnoredPackage(pkgPath) {
							continue
						}
						// check if same package?
						if pkgPath == pass.Pkg.Path() {
							if globalConfig.ReportInternalErrors {
								pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sig)
							}
							continue
						}
