			}
		}
	}
	return nil
}

func (g globPattern) Match(s string) bool {
	return g.re.MatchString(s)
}

func run(pass *analysis.Pass) (interface{}, error) {
	// compile regexps and globs per package (to get per-package error duplication)
	for _, pat := range globalConfig.IgnoreSigRegexps {
		if _, err := regexp.Compile(pat); err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", pat, err.Error())
		}
	}
	for _, pat := range globalConfig.IgnoreInterfaceRegexps {
		if _, err := regexp.Compile(pat); err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", pat, err.Error())
		}
	}
	// compile globs (per package, to duplicate errors)
	for _, pat := range globalConfig.IgnorePackageGlobs {
		if _, err := compileGlob(pat); err != nil {
			// replicate buggy formatting with nil
			return nil, fmt.Errorf("unable to compile globs %s: %s\n", nil, err.Error())
		}
	}
	// re-compile for actual use (cache)
	compiledSigRegexps = nil
	for _, pat := range globalConfig.IgnoreSigRegexps {
		re, _ := regexp.Compile(pat)
		compiledSigRegexps = append(compiledSigRegexps, re)
	}
	compiledIfaceRegexps = nil
	for _, pat := range globalConfig.IgnoreInterfaceRegexps {
		re, _ := regexp.Compile(pat)
		compiledIfaceRegexps = append(compiledIfaceRegexps, re)
	}
	compiledGlobs = nil
	for _, pat := range globalConfig.IgnorePackageGlobs {
		g, _ := compileGlob(pat)
		compiledGlobs = append(compiledGlobs, g)
	}

	// build ignoreSigs list
	ignoreSigs := globalConfig.IgnoreSigs

	// collect assignments
	type assignInfo struct {
		obj  types.Object
		pos  token.Pos
		call *ast.CallExpr // nil if not a call
	}
	var assigns []assignInfo

	// helper to get object for ident (defs or uses)
	getObject := func(id *ast.Ident) types.Object {
		if obj, ok := pass.TypesInfo.Defs[id]; ok && obj != nil {
			return obj
		}
		if obj, ok := pass.TypesInfo.Uses[id]; ok {
			return obj
		}
		return nil
	}

	// collect ValueSpecs and AssignStmts in all files
	for _, f := range pass.Files {
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.ValueSpec:
				if len(x.Values) == 0 {
					// var err error (no values) -> record as non-call for each name?
					for _, name := range x.Names {
						obj := getObject(name)
						if obj == nil {
							continue
						}
						// only record if type is error? Or record all? For simplicity record all with nil call
						// Check if name is error-typed? Actually for var without values, type may be error.
						// Record as non-call
						assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: nil})
					}
				} else if len(x.Values) == 1 {
					if call, ok := x.Values[0].(*ast.CallExpr); ok {
						for _, name := range x.Names {
							obj := getObject(name)
							if obj == nil {
								continue
							}
							assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: call})
						}
					} else {
						// RHS not a call -> record as non-call?
						for _, name := range x.Names {
							obj := getObject(name)
							if obj == nil {
								continue
							}
							assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: nil})
						}
					}
				} else {
					// multiple values (e.g., var x, err = 1, foo()) -> ignore per observed (multiple RHS ignored)
					// Do not record? Or record as non-call? For safety, do not record (so return won't be considered from call)
					// Actually for `var x, err = 1, extlib.A()` with multiple RHS, observed? Not tested, but likely ignored.
					// So skip.
				}
			case *ast.AssignStmt:
				if len(x.Rhs) == 1 {
					if call, ok := x.Rhs[0].(*ast.CallExpr); ok {
						for _, lhs := range x.Lhs {
							if id, ok := lhs.(*ast.Ident); ok {
								obj := getObject(id)
								if obj == nil {
									continue
								}
								// blank identifier? skip?
								if obj.Name() == "_" {
									continue
								}
								assigns = append(assigns, assignInfo{obj: obj, pos: id.Pos(), call: call})
							} else {
								// e.g., a[0], s.f? ignore
							}
						}
					} else {
						// RHS not a call -> record as non-call for each LHS ident?
						for _, lhs := range x.Lhs {
							if id, ok := lhs.(*ast.Ident); ok {
								obj := getObject(id)
								if obj == nil {
									continue
								}
								if obj.Name() == "_" {
									continue
								}
								assigns = append(assigns, assignInfo{obj: obj, pos: id.Pos(), call: nil})
							}
						}
					}
				} else {
					// multiple RHS (e.g., x, err = 1, foo()) -> ignore per observed
					// Do not record
				}
			}
			return true
		})
	}

	// helper to find last assignment before pos for object
	findLastAssign := func(obj types.Object, before token.Pos) *assignInfo {
		var best *assignInfo
		beforeOffset := pass.Fset.Position(before).Offset
		// Need file? Use offset? Better use pos comparison via Fset? Since pos are comparable across files? token.Pos is global, comparable with <?
		// Use pos < before
		for i := range assigns {
			a := &assigns[i]
			if a.obj != obj {
				continue
			}
			if a.pos >= before {
				continue
			}
			if best == nil || best.pos < a.pos {
				// need to copy? Use index
				best = a
			}
		}
		return best
	}

	// helper to check if type is error (exactly error interface)
	errorObj := types.Universe.Lookup("error")
	var errorType types.Type
	if errorObj != nil {
		errorType = errorObj.Type()
	}
	isErrorType := func(t types.Type) bool {
		if t == nil || errorType == nil {
			return false
		}
		// check if t is exactly error (interface with no methods? Actually error is interface with Error() string)
		// Use types.Identical?
		return types.Identical(t, errorType)
	}

	// helper to get func object for call
	getFuncObject := func(call *ast.CallExpr) types.Object {
		switch fun := call.Fun.(type) {
		case *ast.SelectorExpr:
			// check selections (method) vs package func
			if sel, ok := pass.TypesInfo.Selections[fun]; ok {
				return sel.Obj()
			}
			// package func: Uses[Sel]
			if obj, ok := pass.TypesInfo.Uses[fun.Sel]; ok {
				return obj
			}
			return nil
		case *ast.Ident:
			if obj, ok := pass.TypesInfo.Uses[fun]; ok {
				return obj
			}
			return nil
		default:
			// e.g., FuncLit call: fun is *ast.FuncLit or *ast.ParenExpr etc.
			return nil
		}
	}

	// helper to get signature string
	getSig := func(obj types.Object) string {
		if obj == nil {
			return ""
		}
		return obj.String()
	}

	// helper to check if call returns error (for CallExpr direct)
	callReturnsError := func(obj types.Object) bool {
		if obj == nil {
			return false
		}
		fn, ok := obj.(*types.Func)
		if !ok {
			return false
		}
		sig, ok := fn.Type().(*types.Signature)
		if !ok {
			return false
		}
		res := sig.Results()
		for i := 0; i < res.Len(); i++ {
			if isErrorType(res.At(i).Type()) {
				return true
			}
		}
		return false
	}

	// helper to check ignoreSigs substring
	isIgnoredSig := func(sig string) bool {
		for _, s := range ignoreSigs {
			if strings.Contains(sig, s) {
				return true
			}
		}
		for _, re := range compiledSigRegexps {
			if re.MatchString(sig) {
				return true
			}
		}
		return false
	}

	// helper to check package globs
	isIgnoredPackage := func(pkgPath string) bool {
		for _, g := range compiledGlobs {
			if g.Match(pkgPath) {
				return true
			}
		}
		return false
	}

	// helper to get package path for func object
	getPkgPath := func(obj types.Object) string {
		if obj == nil {
			return ""
		}
		if pkg := obj.Pkg(); pkg != nil {
			return pkg.Path()
		}
		return ""
	}

	// helper to check if selection is interface method and get interface name
	getInterfaceName := func(call *ast.CallExpr) (string, bool) {
		selExpr, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return "", false
		}
		sel, ok := pass.TypesInfo.Selections[selExpr]
		if !ok {
			return "", false
		}
		if sel.Kind() != types.MethodVal {
			return "", false
		}
		recv := sel.Recv()
		// recv is the type of X (e.g., io.Reader for r.Read where r is io.Reader)
		// Need to get underlying interface
		// recv may be *types.Named or *types.Interface?
		// For r.Read where r is io.Reader (interface), recv is io.Reader (named? Actually interface type)
		// Use types.AsInterface?
		if iface, ok := recv.(interface{ NumMethods() int }); ok {
			_ = iface
		}
		// Check if recv is interface
		// recv could be named type whose underlying is interface? Or directly interface?
		var ifaceType types.Type
		// If recv is *types.Named, get underlying?
		if named, ok := recv.(*types.Named); ok {
			// check if underlying is interface?
			if _, ok := named.Underlying().(*types.Interface); ok {
				ifaceType = named
			} else {
				return "", false
			}
		} else if _, ok := recv.(*types.Interface); ok {
			ifaceType = recv
		} else {
			return "", false
		}
		_ = ifaceType
		// get package and name for matching: packageName.TypeName
		// For named, get Obj().Pkg().Name() + "." + Obj().Name()
		if named, ok := recv.(*types.Named); ok {
			obj := named.Obj()
			pkg := obj.Pkg()
			if pkg != nil {
				return pkg.Name() + "." + obj.Name(), true
			}
			return obj.Name(), true
		}
		// for direct interface (e.g., error)? Unlikely for methods? error has no methods? Actually error has Error() method, but_recv for error.Error()? That would be interface error?
		// For error interface, what is name? "error"? Let's handle.
		// If recv is *types.Interface (not named), e.g., anonymous interface? Then no name? Return ""?
		return "", false
	}

	// track if function is FuncLit for call skipping
	// Build a set of ReturnStmts inside FuncLit? Instead, during inspection, track parent.
	// We'll inspect each file separately with parent tracking.

	for _, f := range pass.Files {
		// stack to track if inside FuncLit
		var insideFuncLit []bool
		isInsideFuncLit := func() bool {
			for _, b := range insideFuncLit {
				if b {
					return true
				}
			}
			return false
		}
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.FuncLit:
				insideFuncLit = append(insideFuncLit, true)
				return true
			case *ast.FuncDecl:
				insideFuncLit = append(insideFuncLit, false)
				return true
			case *ast.ReturnStmt:
				inLit := isInsideFuncLit()
				// for each result, check
				for _, expr := range x.Results {
					// skip if expr is nil? (shouldn't happen)
					if expr == nil {
						continue
					}
					// If expr is CallExpr
					if call, ok := expr.(*ast.CallExpr); ok {
						if inLit {
							// quirk: direct calls in literals ignored
							continue
						}
						obj := getFuncObject(call)
						if obj == nil {
							continue
						}
						// check if call returns error? If not, skip?
						// For single call with tuple, check Func's results
						if !callReturnsError(obj) {
							// also check if expr type is error? For `return errors.New` where New returns error, callReturnsError true.
							// For `return fmt.Println` where Println returns (int, error) but used as single? It does return error, so true, but should we report? Probably, but unlikely tested.
							// If not returning error, skip.
							continue
						}
						sig := getSig(obj)
						if sig == "" {
							continue
						}
						if isIgnoredSig(sig) {
							continue
						}
						// check interface?
						if ifaceName, ok := getInterfaceName(call); ok {
							// check ignoreInterfaceRegexps
							ignored := false
							for _, re := range compiledIfaceRegexps {
								if re.MatchString(ifaceName) {
									ignored = true
									break
								}
							}
							if !ignored {
								// check package globs for interface? Observed: ignorePackageGlobs does ignore interfaces (e.g., io)
								// For interface, what is package path? Use obj's package?
								pkgPath := getPkgPath(obj)
								if isIgnoredPackage(pkgPath) {
									continue
								}
								pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sig)
								continue
							}
							// else fall through to normal handling (as if not interface)
						}
						// normal handling: check package globs
						pkgPath := getPkgPath(obj)
						if isIgnoredPackage(pkgPath) {
							continue
						}
						// check if same package?
						if pkgPath == pass.Pkg.Path() {
							if globalConfig.ReportInternalErrors {
								pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sig)
							}
							continue
						}
						// external
						pass.Reportf(expr.Pos(), "error returned from external package is unwrapped: sig: %s", sig)
					} else if ident, ok := expr.(*ast.Ident); ok {
						if ident.Name == "nil" {
							continue
						}
						// check if ident type is error?
						t := pass.TypesInfo.TypeOf(ident)
						// TypeOf may be nil for some? Fallback to object type?
						if t == nil {
							if obj := getObject(ident); obj != nil {
								if v, ok := obj.(*types.Var); ok {
									t = v.Type()
								}
							}
						}
						if !isErrorType(t) {
							continue
						}
						obj := getObject(ident)
						if obj == nil {
							continue
						}
						// find last assignment before this return
						assign := findLastAssign(obj, expr.Pos())
						if assign == nil {
							continue
						}
						if assign.call == nil {
							// assigned from non-call (nil, ident, etc.) -> not reported
							continue
						}
						call := assign.call
						// check if call inside FuncLit? No, assignment's call location doesn't matter? The return's location matters for skipping? Already handled return inLit for calls, but for ident returns in literals, we DO report (as observed). So do not skip ident returns in literals.
						obj2 := getFuncObject(call)
						if obj2 == nil {
							continue
						}
						if !callReturnsError(obj2) {
							continue
						}
						sig := getSig(obj2)
						if sig == "" {
							continue
						}
						if isIgnoredSig(sig) {
							continue
						}
						// check interface for the assignment's call?
						if ifaceName, ok := getInterfaceName(call); ok {
							ignored := false
							for _, re := range compiledIfaceRegexps {
								if re.MatchString(ifaceName) {
									ignored = true
									break
								}
							}
							if !ignored {
								pkgPath := getPkgPath(obj2)
								if isIgnoredPackage(pkgPath) {
									continue
								}
								pass.Reportf(expr.Pos(), "error returned from interface method should be wrapped: sig: %s", sig)
								continue
							}
						}
						pkgPath := getPkgPath(obj2)
						if isIgnoredPackage(pkgPath) {
							continue
						}
						if pkgPath == pass.Pkg.Path() {
							if globalConfig.ReportInternalErrors {
								pass.Reportf(expr.Pos(), "package-internal error should be wrapped: sig: %s", sig)
							}
							continue
						}
						pass.Reportf(expr.Pos(), "error returned from external package is unwrapped: sig: %s", sig)
					} else {
						// other expr types (Selector for vars, etc.) -> skip
						// But what about `return f()` where f is ident? That's CallExpr with Fun=Ident, already handled as CallExpr.
						// What about `return (err)` (ParenExpr)? Unwrap?
						// Handle ParenExpr by unwrapping?
						// For simplicity, if ParenExpr, check inner?
						if paren, ok := expr.(*ast.ParenExpr); ok {
							// unwrap one level? Could be nested? For now, handle ident inside?
							// This is edge, unlikely tested. Skip for now.
							_ = paren
							continue
						}
						continue
					}
				}
				return true
			}
			return true
		})
		// pop? Need to handle stack pop on exit. Our Inspect doesn't track exit. Instead, we need to manage with a different approach:
		// The above insideFuncLit stack will grow but never pop, because Inspect calls for each node but we don't know when leaving FuncLit.
		// Fix: use a different traversal that tracks entry/exit, or compute isInsideFuncLit by checking parents via ast path?
		// Simpler: for each ReturnStmt, determine if it's inside FuncLit by searching parents? We don't have parent map.
		// Alternative: precompute set of ReturnStmts inside FuncLit by finding all FuncLits and their returns.
		// Easiest: instead of stack, just for each ReturnStmt, check if any ancestor is FuncLit by walking file? We can do a separate pass.
		_ = x
		_ = insideFuncLit
	}

	return nil, nil
