		return nil, fmt.Errorf("'%s' expected type 'string', got unconvertible type '%s', value: '%s'", field, typeName, valStr)
	}
}

func goTypeName(v interface{}) string {
	switch v.(type) {
	case map[string]interface{}:
		return "map[string]interface {}"
	case []interface{}:
		return "[]interface {}"
	case string:
		return "string"
	case bool:
		return "bool"
	case int:
		return "int"
	case int64:
		return "int64"
	case float64:
		return "float64"
	default:
		// fallback using %T?
		t := fmt.Sprintf("%T", v)
		// mapstructure uses '[]interface {}' etc. with space? Our %T gives '[]interface {}' already? For map, %T gives 'map[string]interface {}' Good.
		return t
	}
}

func decodeBool(field string, v interface{}) (bool, error) {
	if v == nil {
		return false, nil
	}
	switch x := v.(type) {
	case bool:
		return x, nil
	case string:
		b, err := strconv.ParseBool(x)
		if err != nil {
			return false, fmt.Errorf("cannot parse '%s' as bool: %s", field, err.Error())
		}
		return b, nil
	case int:
		return x != 0, nil
	case int64:
		return x != 0, nil
	case float64:
		return x != 0, nil
	case float32:
		return x != 0, nil
	case []interface{}:
		// e.g., reportInternalErrors: [1,2] -> error "'field' expected type 'bool', got unconvertible type '[]interface {}', value: '[1 2]'"
		valStr := fmt.Sprintf("%v", x)
		return false, fmt.Errorf("'%s' expected type 'bool', got unconvertible type '[]interface {}', value: '%s'", field, valStr)
	case map[string]interface{}:
		if len(x) == 0 {
			// observed: empty map gives no error, treated as false
			return false, nil
		}
		valStr := fmt.Sprintf("%v", x)
		return false, fmt.Errorf("'%s' expected type 'bool', got unconvertible type 'map[string]interface {}', value: '%s'", field, valStr)
	default:
		// check for yaml int types? yaml.v3 decodes ints as int, floats as float64, etc.
		// Use reflection? For now, try string conversion?
		// If it's e.g., uint64?
		s := fmt.Sprintf("%v", v)
		// try ParseBool?
		if b, err := strconv.ParseBool(s); err == nil {
			return b, nil
		}
		typeName := fmt.Sprintf("%T", v)
		return false, fmt.Errorf("'%s' expected type 'bool', got unconvertible type '%s', value: '%s'", field, typeName, s)
	}
}

// globPattern holds compiled glob.
type globPattern struct {
	raw string
	re  *regexp.Regexp
}

func compileGlob(pat string) (globPattern, error) {
	reStr, err := globToRegexp(pat)
	if err != nil {
		return globPattern{}, err
	}
	re, err := regexp.Compile(reStr)
	if err != nil {
		// shouldn't happen, but return as glob error?
		return globPattern{}, err
	}
	return globPattern{raw: pat, re: re}, nil
}

func globToRegexp(pat string) (string, error) {
	var sb strings.Builder
	sb.WriteString("^")
	i := 0
	n := len(pat)
	for i < n {
		c := pat[i]
		switch c {
		case '*':
			// check for **? treat same as * (both cross /)
			if i+1 < n && pat[i+1] == '*' {
				// ** -> .*
				sb.WriteString(".*")
				i += 2
				// if **/ ? keep as .* (already)
			} else {
				sb.WriteString(".*")
				i++
			}
		case '?':
			sb.WriteString(".")
			i++
		case '[':
			// find closing ]
			j := i + 1
			if j < n && pat[j] == '!' || pat[j] == '^' {
				j++
			}
			// handle []? e.g., []a]? need to handle ] as first char?
			if j < n && pat[j] == ']' {
				j++
			}
			for j < n && pat[j] != ']' {
				// handle escape?
				if pat[j] == '\\' && j+1 < n {
					j += 2
				} else {
					j++
				}
			}
			if j >= n {
				return "", fmt.Errorf("unexpected end of input")
			}
			// extract content inside []
			inner := pat[i+1 : j]
			// check for invalid range like [z-a]
			// parse inner to detect hi < lo
			if err := checkCharClass(inner); err != nil {
				return "", err
			}
			// copy as is (including brackets) to regex (need to escape? [] in regex is same)
			// But need to handle ! at start -> ^ in regex?
			// gobwas/glob uses ! or ^? Let's handle both as ^?
			// For simplicity, copy inner with translation of ! to ^?
			// Actually glob [^...] vs [!...]? Both mean negation? We'll support both.
			sb.WriteString("[" + inner + "]")
			i = j + 1
		case '{':
			// find matching }
			depth := 1
			j := i + 1
			for j < n && depth > 0 {
				if pat[j] == '{' {
					depth++
				} else if pat[j] == '}' {
					depth--
					if depth == 0 {
						break
					}
				} else if pat[j] == '\\' && j+1 < n {
					j++
				}
				j++
			}
			if depth != 0 {
				return "", fmt.Errorf("unexpected end of input")
			}
			inner := pat[i+1 : j]
			// split by , at depth 0 (no nesting for simplicity, split all)
			parts := splitAlternatives(inner)
			sb.WriteString("(?:")
			for k, p := range parts {
				if k > 0 {
					sb.WriteString("|")
				}
				// recursively convert each part? For simplicity, convert * ? etc. in part
				// We'll call globToRegexpInner for part without {}? To avoid recursion issues, just convert * ? etc.
				// For now, escape regex chars except * ? [] already handled? This is complex.
				// Simplify: convert part by replacing * with .* etc., without handling nested {} []?
				// We'll implement helper.
				r, err := globPartToRegexp(p)
				if err != nil {
					return "", err
				}
				// r includes ^$? No, helper returns without anchors, so strip?
				// Our helper will return without ^$, so use directly.
				sb.WriteString(r)
			}
			sb.WriteString(")")
			i = j + 1
		case '\\':
			if i+1 < n {
				sb.WriteString(regexp.QuoteMeta(string(pat[i+1])))
				i += 2
			} else {
				sb.WriteString(`\\`)
				i++
			}
		default:
			sb.WriteString(regexp.QuoteMeta(string(c)))
			i++
		}
	}
	sb.WriteString("$")
	return sb.String(), nil
}

func globPartToRegexp(p string) (string, error) {
	var sb strings.Builder
	i := 0
	n := len(p)
	for i < n {
		c := p[i]
		switch c {
		case '*':
			sb.WriteString(".*")
			i++
		case '?':
			sb.WriteString(".")
			i++
		case '[':
			j := i + 1
			if j < n && (p[j] == '!' || p[j] == '^') {
				j++
			}
			if j < n && p[j] == ']' {
				j++
			}
			for j < n && p[j] != ']' {
				if p[j] == '\\' && j+1 < n {
					j += 2
				} else {
					j++
				}
			}
			if j >= n {
				return "", fmt.Errorf("unexpected end of input")
			}
			inner := p[i+1 : j]
			if err := checkCharClass(inner); err != nil {
				return "", err
			}
			sb.WriteString("[" + inner + "]")
			i = j + 1
		case '\\':
			if i+1 < n {
				sb.WriteString(regexp.QuoteMeta(string(p[i+1])))
				i += 2
			} else {
				sb.WriteString(`\\`)
				i++
			}
		default:
			sb.WriteString(regexp.QuoteMeta(string(c)))
			i++
		}
	}
	return sb.String(), nil
}

func splitAlternatives(s string) []string {
	var parts []string
	depth := 0
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			i++
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
		} else if c == ',' && depth == 0 {
			parts = append(parts, s[start:i])
			start = i + 1
		}
	}
	parts = append(parts, s[start:])
	return parts
}

func checkCharClass(inner string) error {
	// inner is content inside [], e.g., "abc", "z-a", "!abc"
	// Need to detect invalid range where hi < lo, e.g., [z-a] -> "hi character 'a' should be greater than lo 'z'"
	// Parse inner: handle leading ! or ^ as negation, then parse chars and ranges
	s := inner
	if len(s) > 0 && (s[0] == '!' || s[0] == '^') {
		s = s[1:]
	}
	// handle ] as first char? Already handled in caller, but for check, if s starts with ]? That's literal ]? Our caller handled ] as first char by including it? Actually caller includes ] handling, but inner may start with ]? Let's just parse.
	i := 0
	// if first char is ], it's literal, skip?
	if len(s) > 0 && s[0] == ']' {
		i = 1
	}
	for i < len(s) {
		// handle escape?
		var lo byte
		if s[i] == '\\' && i+1 < len(s) {
			lo = s[i+1]
			i += 2
		} else {
			lo = s[i]
			i++
		}
		if i < len(s) && s[i] == '-' {
			// range?
			if i+1 >= len(s) {
				// trailing - is literal, ok
				break
			}
			var hi byte
			if s[i+1] == '\\' && i+2 < len(s) {
				hi = s[i+2]
				i += 3
			} else {
				hi = s[i+1]
				i += 2
			}
			if hi < lo {
				return fmt.Errorf("hi character '%c' should be greater than lo '%c'", hi, lo)
			}
		}
	}
	return nil
}

func (g globPattern) Match(s string) bool {
	return g.re.MatchString(s)
}

func run(pass *analysis.Pass) (interface{}, error) {
	// compile regexps and globs per package (to get per-package error duplication)
	for _, pat := range globalConfig.IgnoreSigRegexps {
		if _, err := regexp.Compile(pat); err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", pat, err.Error())
		}
	}
	for _, pat := range globalConfig.IgnoreInterfaceRegexps {
		if _, err := regexp.Compile(pat); err != nil {
			return nil, fmt.Errorf("unable to compile regexp %s: %s\n", pat, err.Error())
		}
	}
	// compile globs (per package, to duplicate errors)
	for _, pat := range globalConfig.IgnorePackageGlobs {
		if _, err := compileGlob(pat); err != nil {
			// replicate buggy formatting with nil
			return nil, fmt.Errorf("unable to compile globs %s: %s\n", nil, err.Error())
		}
	}
	// re-compile for actual use (cache)
	compiledSigRegexps = nil
	for _, pat := range globalConfig.IgnoreSigRegexps {
		re, _ := regexp.Compile(pat)
		compiledSigRegexps = append(compiledSigRegexps, re)
	}
	compiledIfaceRegexps = nil
	for _, pat := range globalConfig.IgnoreInterfaceRegexps {
		re, _ := regexp.Compile(pat)
		compiledIfaceRegexps = append(compiledIfaceRegexps, re)
	}
	compiledGlobs = nil
	for _, pat := range globalConfig.IgnorePackageGlobs {
		g, _ := compileGlob(pat)
		compiledGlobs = append(compiledGlobs, g)
	}

	// build ignoreSigs list
	ignoreSigs := globalConfig.IgnoreSigs

	// collect assignments
	type assignInfo struct {
		obj  types.Object
		pos  token.Pos
		call *ast.CallExpr // nil if not a call
	}
	var assigns []assignInfo

	// helper to get object for ident (defs or uses)
	getObject := func(id *ast.Ident) types.Object {
		if obj, ok := pass.TypesInfo.Defs[id]; ok && obj != nil {
			return obj
		}
		if obj, ok := pass.TypesInfo.Uses[id]; ok {
			return obj
		}
		return nil
	}

	// collect ValueSpecs and AssignStmts in all files
	for _, f := range pass.Files {
		ast.Inspect(f, func(n ast.Node) bool {
			switch x := n.(type) {
			case *ast.ValueSpec:
				if len(x.Values) == 0 {
					// var err error (no values) -> record as non-call for each name?
					for _, name := range x.Names {
						obj := getObject(name)
						if obj == nil {
							continue
						}
						// only record if type is error? Or record all? For simplicity record all with nil call
						// Check if name is error-typed? Actually for var without values, type may be error.
						// Record as non-call
						assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: nil})
					}
				} else if len(x.Values) == 1 {
					if call, ok := x.Values[0].(*ast.CallExpr); ok {
						for _, name := range x.Names {
							obj := getObject(name)
							if obj == nil {
								continue
							}
							assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: call})
						}
					} else {
						// RHS not a call -> record as non-call?
						for _, name := range x.Names {
							obj := getObject(name)
							if obj == nil {
								continue
							}
							assigns = append(assigns, assignInfo{obj: obj, pos: name.Pos(), call: nil})
						}
					}
				} else {
					// multiple values (e.g., var x, err = 1, foo()) -> ignore per observed (multiple RHS ignored)
					// Do not record? Or record as non-call? For safety, do not record (so return won't be considered from call)
					// Actually for `var x, err = 1, extlib.A()` with multiple RHS, observed? Not tested, but likely ignored.
					// So skip.
				}
			case *ast.AssignStmt:
				if len(x.Rhs) == 1 {
					if call, ok := x.Rhs[0].(*ast.CallExpr); ok {
						for _, lhs := range x.Lhs {
							if id, ok := lhs.(*ast.Ident); ok {
								obj := getObject(id)
								if obj == nil {
									continue
								}
								// blank identifier? skip?
								if obj.Name() == "_" {
									continue
								}
								assigns = append(assigns, assignInfo{obj: obj, pos: id.Pos(), call: call})
